// Parse intent signal and determine notification strategy
const items = $input.all();
const notifications = [];

for (const item of items) {
  const body = item.json.body || item.json;

  const intentScore = parseFloat(body.intent_score) || 0;
  const intentLevel = body.intent_level || 'cold';

  // Determine SLA window based on intent
  let slaWindow, slackChannel, urgency;

  if (intentLevel === 'declared' || intentScore >= 80) {
    slaWindow = '15 min';
    slackChannel = '#hot-leads';
    urgency = '🚨 CRÍTICO';
  } else if (intentLevel === 'immediate' || intentScore >= 50) {
    slaWindow = '1 hora';
    slackChannel = '#hot-leads';
    urgency = '🔥 URGENTE';
  } else if (intentLevel === 'boiling' || intentScore >= 30) {
    slaWindow = '4 horas';
    slackChannel = '#growth-leads';
    urgency = '⚡ QUENTE';
  } else {
    slaWindow = '24 horas';
    slackChannel = '#growth-leads';
    urgency = '📊 MORN';
  }

  notifications.push({
    json: {
      session_id: body.session_id,
      lead_id: body.lead_id || body.avails_id,
      lead_nutshell_id: body.nutshell_contact_id,
      lead_name: body.lead_name || 'Contato',
      lead_email: body.lead_email || '',
      lead_phone: body.lead_phone || '',
      lead_first_name: (body.lead_name || '').split(' ')[0],
      city: body.city || 'N/A',
      state: body.state || '',
      vertical: body.vertical || 'solar',
      category: body.category || '',
      energy_bill: body.energy_bill || 'N/A',
      intent_score: intentScore,
      intent_level: intentLevel,
      sla_window: slaWindow,
      slack_channel: slackChannel,
      notify_slack: true,
      manual_distribution_required: true,
      urgency: urgency,
      slack_message: `${urgency} Lead de Alta Intenção Detectado!\n\n👤 *${body.lead_name || 'Contato'}*\n📧 ${body.lead_email || 'N/A'}\n📱 ${body.lead_phone || 'N/A'}\n🏙️ ${body.city || 'N/A'}, ${body.state || ''}\n☀️ ${body.vertical || 'solar'} | ${body.category || ''}\n💰 Conta: R$ ${body.energy_bill || 'N/A'}\n\n📊 *Intent Score:* ${intentScore}/100\n🏷️ *Intent Level:* ${intentLevel}\n⏰ *SLA:* Responder em ${slaWindow}\n🧭 *Ação:* distribuir manualmente e registrar no CRM\n🆔 *ID:* ${body.lead_id || body.avails_id || body.session_id}`,
      created_at: new Date().toISOString()
    }
  });
}

return notifications;
